import React from 'react';
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import 'bootstrap/dist/css/bootstrap.min.css';
import Cadastro from './Telas/Cadastro';
import Detalhes from './Telas/Detalhes';
import DrawerMenu from './Telas/DrawerMenu';
import Home from './Telas/Home'; // Adicione a importação da nova página
import './Estilo/App.css'; // Caminho atualizado para o arquivo CSS

function App() {
  return (
    <Router>
      <DrawerMenu />
      <div style={{ marginLeft: '250px' }}> {/* Ajuste o espaçamento conforme a largura do menu */}
        <Routes>
          <Route path="/" element={<Home />} /> {/* Página inicial */}
          <Route path="/cadastro" element={<Cadastro />} />
          <Route path="/detalhes" element={<Detalhes />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
